//! preparing quizzes, questions and options, plus a playable preview.
//!
//! Run with: PORT=3000 SECRET_KEY_BASE=... QUIZZY_MODERATOR_USERNAME=... \
//!           QUIZZY_MODERATOR_PASSWORD=... ./bin/serve
//!
//! SECRET_KEY_BASE is accepted for forward compatibility (session signing in
//! later releases); this release keeps no session state.

mod db;
mod game;
mod httpd;
mod json;
mod routes;
mod transfer;
mod views;

use std::sync::Arc;

fn main() {
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(3000);
    let state = Arc::new(routes::State {
        db_path: std::env::var("QUIZZY_DATABASE_PATH")
            .unwrap_or_else(|_| "storage/quizzy.db".to_string()),
        moderator_username: std::env::var("QUIZZY_MODERATOR_USERNAME").unwrap_or_default(),
        moderator_password: std::env::var("QUIZZY_MODERATOR_PASSWORD").unwrap_or_default(),
        port,
    });

    // Everything the app stores lives under storage/.
    if let Some(parent) = std::path::Path::new(&state.db_path).parent() {
        std::fs::create_dir_all(parent).expect("cannot create storage directory");
    }
    {
        let conn = db::connect(&state.db_path).expect("cannot open the database");
        db::migrate(&conn).expect("cannot migrate the database");
    }

    let server = tiny_http::Server::http(("0.0.0.0", port))
        .unwrap_or_else(|e| panic!("cannot listen on port {port}: {e}"));
    println!("Quizzy is ready on http://0.0.0.0:{port}");
    let server = Arc::new(server);

    let workers = std::thread::available_parallelism().map(|n| n.get().clamp(8, 32)).unwrap_or(8);
    let mut handles = Vec::new();
    for _ in 0..workers {
        let server = Arc::clone(&server);
        let state = Arc::clone(&state);
        handles.push(std::thread::spawn(move || loop {
            match server.recv() {
                Ok(request) => {
                    let state = Arc::clone(&state);
                    httpd::dispatch(request, &move |req| routes::handle(req, &state));
                }
                Err(_) => continue,
            }
        }));
    }
    for h in handles {
        let _ = h.join();
    }
}
//! Live game support: join-code and token generation, QR codes, the game
//! phase machine, and the shared live-updating JavaScript.

use crate::db::{self, Game, GameStatus, Question, Quiz};
use rusqlite::Connection;

/// Unambiguous alphabet for join codes (no 0/O, 1/I).
const CODE_ALPHABET: &[u8] = b"ABCDEFGHJKLMNPQRSTUVWXYZ23456789";

/// Read random bytes from /dev/urandom, with a time-based fallback.
fn random_bytes(n: usize) -> Vec<u8> {
    use std::io::Read;
    if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
        let mut buf = vec![0u8; n];
        if f.read_exact(&mut buf).is_ok() {
            return buf;
        }
    }
    // Fallback: hash the current time, pid and address of a stack value.
    let mut out = Vec::with_capacity(n);
    let mut seed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0x9e3779b97f4a7c15)
        ^ (std::process::id() as u64) << 32;
    while out.len() < n {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        out.extend_from_slice(&seed.to_le_bytes());
    }
    out.truncate(n);
    out
}

/// A short join code like "K7RZX".
pub fn join_code() -> String {
    random_bytes(5)
        .iter()
        .map(|b| (CODE_ALPHABET[(b % 32) as usize]) as char)
        .collect()
}

/// A player cookie token (URL- and cookie-safe hex).
pub fn player_token() -> String {
    random_bytes(16).iter().map(|b| format!("{b:02x}")).collect()
}

/// FNV-1a hash of the fragment, used as the live-update version: the page
/// only re-renders when the visible content actually changed.
pub fn version_of(fragment: &str) -> String {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in fragment.as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    format!("{h:016x}")
}

/// Render `text` as an inline SVG QR code (dark modules on the design's
/// night ink; the .qr container provides the white quiet zone).
pub fn qr_svg(text: &str) -> String {
    use qrcodegen::{QrCode, QrCodeEcc};
    let Ok(qr) = QrCode::encode_text(text, QrCodeEcc::Medium) else {
        return String::new();
    };
    let size = qr.size();
    let mut d = String::new();
    for y in 0..size {
        for x in 0..size {
            if qr.get_module(x, y) {
                d.push_str(&format!("M{x} {y}h1v1h-1z"));
            }
        }
    }
    format!(
        r##"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {size} {size}" shape-rendering="crispEdges"><path d="{d}" fill="#0d0640"/></svg>"##
    )
}

