//!
//! Schema: quizzes have questions (ordered by `position`), questions have
//! options (ordered by `position`). Deleting a quiz cascades to its questions
//! and options through foreign keys.

use rusqlite::{Connection, Result, params};

#[derive(Debug, Clone)]
pub struct Quiz {
    pub id: i64,
    pub title: String,
}

#[derive(Debug, Clone)]
pub struct Question {
    pub id: i64,
    pub quiz_id: i64,
    pub position: i64,
    pub text: String,
    pub active: bool,
    pub options: Vec<Opt>,
}

#[derive(Debug, Clone)]
pub struct Opt {
    pub id: i64,
    pub text: String,
    pub correct: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub enum GameStatus {
    Lobby,
    Playing,
    Finished,
}

/// One run of a quiz: its own join code, players and answers.
#[derive(Debug, Clone)]
pub struct Game {
    pub id: i64,
    pub quiz_id: i64,
    pub code: String,
    pub status: GameStatus,
    pub question_id: Option<i64>,
    pub question_open: bool,
}

/// A player of one game, remembered by a cookie token (no account).
#[derive(Debug, Clone)]
pub struct Player {
    pub id: i64,
    pub name: String,
}

pub struct QuizSummary {
    pub quiz: Quiz,
    pub total_questions: i64,
    pub active_questions: i64,
}

/// Open a connection with the pragmas every connection needs.
pub fn connect(path: &str) -> Result<Connection> {
    let conn = Connection::open(path)?;
    conn.execute_batch(
        "PRAGMA foreign_keys = ON;
         PRAGMA busy_timeout = 5000;",
    )?;
    Ok(conn)
}

/// Create the schema if it does not exist yet. Safe to run on every boot.
pub fn migrate(conn: &Connection) -> Result<()> {
    conn.execute_batch(
        "PRAGMA journal_mode = WAL;

         CREATE TABLE IF NOT EXISTS quizzes (
           id         INTEGER PRIMARY KEY AUTOINCREMENT,
           title      TEXT NOT NULL,
           created_at TEXT NOT NULL DEFAULT (datetime('now'))
         );

         CREATE TABLE IF NOT EXISTS questions (
           id       INTEGER PRIMARY KEY AUTOINCREMENT,
           quiz_id  INTEGER NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
           position INTEGER NOT NULL,
           text     TEXT NOT NULL,
           active   INTEGER NOT NULL DEFAULT 1
         );
         CREATE INDEX IF NOT EXISTS idx_questions_quiz ON questions(quiz_id, position);

         CREATE TABLE IF NOT EXISTS options (
           id          INTEGER PRIMARY KEY AUTOINCREMENT,
           question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
           position    INTEGER NOT NULL,
           text        TEXT NOT NULL,
           correct     INTEGER NOT NULL DEFAULT 0
         );
         CREATE INDEX IF NOT EXISTS idx_options_question ON options(question_id, position);

         CREATE TABLE IF NOT EXISTS games (
           id            INTEGER PRIMARY KEY AUTOINCREMENT,
           quiz_id       INTEGER NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
           code          TEXT NOT NULL UNIQUE,
           status        TEXT NOT NULL DEFAULT 'lobby',
           question_id   INTEGER REFERENCES questions(id) ON DELETE SET NULL,
           question_open INTEGER NOT NULL DEFAULT 0,
           created_at    TEXT NOT NULL DEFAULT (datetime('now'))
         );
         CREATE INDEX IF NOT EXISTS idx_games_quiz ON games(quiz_id);

         CREATE TABLE IF NOT EXISTS players (
           id         INTEGER PRIMARY KEY AUTOINCREMENT,
           game_id    INTEGER NOT NULL REFERENCES games(id) ON DELETE CASCADE,
           name       TEXT NOT NULL,
           token      TEXT NOT NULL,
           created_at TEXT NOT NULL DEFAULT (datetime('now'))
         );
         CREATE INDEX IF NOT EXISTS idx_players_game ON players(game_id);
         CREATE INDEX IF NOT EXISTS idx_players_token ON players(game_id, token);

         CREATE TABLE IF NOT EXISTS answers (
           player_id   INTEGER NOT NULL REFERENCES players(id) ON DELETE CASCADE,
           question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
           option_id   INTEGER NOT NULL REFERENCES options(id) ON DELETE CASCADE,
           updated_at  TEXT NOT NULL DEFAULT (datetime('now')),
           PRIMARY KEY (player_id, question_id)
         );",
    )?;
    Ok(())
}

