pub fn list_quizzes(conn: &Connection) -> Result<Vec<QuizSummary>> {
    let mut stmt = conn.prepare(
        "SELECT q.id, q.title,
                (SELECT COUNT(*) FROM questions WHERE quiz_id = q.id),
                (SELECT COUNT(*) FROM questions WHERE quiz_id = q.id AND active = 1)
         FROM quizzes q ORDER BY q.id",
    )?;
    let rows = stmt.query_map([], |row| {
        Ok(QuizSummary {
            quiz: Quiz { id: row.get(0)?, title: row.get(1)? },
            total_questions: row.get(2)?,
            active_questions: row.get(3)?,
        })
    })?;
    rows.collect()
}

