pub fn get_quiz(conn: &Connection, id: i64) -> Result<Option<Quiz>> {
    let mut stmt = conn.prepare("SELECT id, title FROM quizzes WHERE id = ?1")?;
    let mut rows = stmt.query(params![id])?;
    match rows.next()? {
        Some(row) => Ok(Some(Quiz { id: row.get(0)?, title: row.get(1)? })),
        None => Ok(None),
    }
}

pub fn update_quiz(conn: &Connection, id: i64, title: &str) -> Result<()> {
    conn.execute("UPDATE quizzes SET title = ?2 WHERE id = ?1", params![id, title])?;
    Ok(())
}

pub fn delete_quiz(conn: &Connection, id: i64) -> Result<()> {
    conn.execute("DELETE FROM quizzes WHERE id = ?1", params![id])?;
    Ok(())
}

/// Insert a quiz with all its questions in one transaction, so an import
/// either lands completely or not at all. `questions` is a list of
/// (text, active, options) triples in display order.
pub fn import_quiz(
    conn: &mut Connection,
    title: &str,
    questions: &[(String, bool, Vec<(String, bool)>)],
) -> Result<i64> {
    let tx = conn.transaction()?;
    let quiz_id = create_quiz(&tx, title)?;
    for (text, active, options) in questions {
        create_question(&tx, quiz_id, text, *active, options)?;
    }
    tx.commit()?;
    Ok(quiz_id)
}

// ---------- Questions ----------

pub fn list_questions(conn: &Connection, quiz_id: i64) -> Result<Vec<Question>> {
    let mut stmt = conn.prepare(
        "SELECT id, quiz_id, position, text, active FROM questions
         WHERE quiz_id = ?1 ORDER BY position, id",
    )?;
    let rows = stmt.query_map(params![quiz_id], |row| {
        Ok(Question {
            id: row.get(0)?,
            quiz_id: row.get(1)?,
            position: row.get(2)?,
            text: row.get(3)?,
            active: row.get::<_, i64>(4)? != 0,
            options: Vec::new(),
        })
    })?;
    let mut questions: Vec<Question> = rows.collect::<Result<_>>()?;
    for q in &mut questions {
        q.options = list_options(conn, q.id)?;
    }
    Ok(questions)
}

pub fn get_question(conn: &Connection, id: i64) -> Result<Option<Question>> {
    let mut stmt =
        conn.prepare("SELECT id, quiz_id, position, text, active FROM questions WHERE id = ?1")?;
    let mut rows = stmt.query(params![id])?;
    match rows.next()? {
        Some(row) => {
            let mut q = Question {
                id: row.get(0)?,
                quiz_id: row.get(1)?,
                position: row.get(2)?,
                text: row.get(3)?,
                active: row.get::<_, i64>(4)? != 0,
                options: Vec::new(),
            };
            q.options = list_options(conn, q.id)?;
            Ok(Some(q))
        }
        None => Ok(None),
    }
}

fn list_options(conn: &Connection, question_id: i64) -> Result<Vec<Opt>> {
    let mut stmt = conn.prepare(
        "SELECT id, text, correct FROM options WHERE question_id = ?1 ORDER BY position, id",
    )?;
    let rows = stmt.query_map(params![question_id], |row| {
        Ok(Opt { id: row.get(0)?, text: row.get(1)?, correct: row.get::<_, i64>(2)? != 0 })
    })?;
    rows.collect()
}

/// `options` is a list of (text, correct) pairs in display order.
pub fn create_question(
    conn: &Connection,
    quiz_id: i64,
    text: &str,
    active: bool,
    options: &[(String, bool)],
) -> Result<i64> {
    let position: i64 = conn.query_row(
        "SELECT COALESCE(MAX(position), 0) + 1 FROM questions WHERE quiz_id = ?1",
        params![quiz_id],
        |row| row.get(0),
    )?;
    conn.execute(
        "INSERT INTO questions (quiz_id, position, text, active) VALUES (?1, ?2, ?3, ?4)",
        params![quiz_id, position, text, active as i64],
    )?;
    let id = conn.last_insert_rowid();
    insert_options(conn, id, options)?;
    Ok(id)
}

/// Replace text/active/options of an existing question (position untouched).
pub fn update_question(
    conn: &Connection,
    id: i64,
    text: &str,
    active: bool,
    options: &[(String, bool)],
) -> Result<()> {
    conn.execute(
        "UPDATE questions SET text = ?2, active = ?3 WHERE id = ?1",
        params![id, text, active as i64],
    )?;
    conn.execute("DELETE FROM options WHERE question_id = ?1", params![id])?;
    insert_options(conn, id, options)?;
    Ok(())
}

fn insert_options(conn: &Connection, question_id: i64, options: &[(String, bool)]) -> Result<()> {
    let mut stmt =
        conn.prepare("INSERT INTO options (question_id, position, text, correct) VALUES (?1, ?2, ?3, ?4)")?;
    for (i, (text, correct)) in options.iter().enumerate() {
        stmt.execute(params![question_id, (i + 1) as i64, text, *correct as i64])?;
    }
    Ok(())
}

pub fn delete_question(conn: &Connection, id: i64) -> Result<()> {
    conn.execute("DELETE FROM questions WHERE id = ?1", params![id])?;
    Ok(())
}

pub fn set_question_active(conn: &Connection, id: i64, active: bool) -> Result<()> {
    conn.execute("UPDATE questions SET active = ?2 WHERE id = ?1", params![id, active as i64])?;
    Ok(())
}

/// Swap a question with its neighbour in the quiz's ordering.
pub fn move_question(conn: &Connection, id: i64, dir: &str) -> Result<()> {
    let Some(q) = get_question(conn, id)? else { return Ok(()) };
    let questions = list_questions(conn, q.quiz_id)?;
    let Some(idx) = questions.iter().position(|x| x.id == id) else { return Ok(()) };
    let other = match dir {
        "up" => idx.checked_sub(1),
        "down" => {
            if idx + 1 < questions.len() { Some(idx + 1) } else { None }
        }
        _ => None,
    };
    if let Some(o) = other {
        let a = &questions[idx];
        let b = &questions[o];
        conn.execute("UPDATE questions SET position = ?2 WHERE id = ?1", params![a.id, b.position])?;
        conn.execute("UPDATE questions SET position = ?2 WHERE id = ?1", params![b.id, a.position])?;
    }
    Ok(())
}

