            else {
                return Resp::text(403, "Not in the game");
            };
            let Some(view) = GameView::load(conn, game.id) else { return Resp::not_found() };
            fragment_resp(views::play_fragment(conn, &view, &player))
        }
        ("POST", ["play", code, "answer"]) => {
            let Some(game) = db::get_game_by_code(conn, code).ok().flatten() else { return Resp::not_found() };
            let cookie = player_cookie(&game.code);
            let Some(player) = req
                .cookie(&cookie)
                .and_then(|token| db::get_player_by_token(conn, game.id, token).ok().flatten())
            else {
                return Resp::text(403, "Not in the game");
            };
            // Only while the question is open, and only one of its options.
            if game.status == GameStatus::Playing && game.question_open {
                if let Some(qid) = game.question_id {
                    if let Some(oid) = req.param("option").and_then(parse_id) {
                        let valid = db::get_question(conn, qid)
                            .ok()
                            .flatten()
                            .map(|q| q.options.iter().any(|o| o.id == oid))
                            .unwrap_or(false);
                        if valid {
                            let _ = db::upsert_answer(conn, player.id, qid, oid);
                        }
                    }
                }
            }
            if req.live {
                Resp::no_content()
            } else {
                Resp::redirect(&format!("/play/{code}"))
            }
        }
        _ => Resp::not_found(),
    }
}
