fn errors_box(errors: &[String]) -> String {
    if errors.is_empty() {
        return String::new();
    }
    let items: Vec<String> = errors.iter().map(|e| format!("<li>{}</li>", esc(e))).collect();
    if errors.len() == 1 {
        format!(r#"      <div class="errors">{}</div>"#, esc(&errors[0]))
    } else {
        format!(r#"      <div class="errors"><ul>{}</ul></div>"#, items.concat())
    }
}

