pub fn pick_draw(board: &[Leader], n: i64) -> Vec<i64> {
    let n = n.max(1) as usize;
    let nth = if board.len() >= n { board[n - 1].points } else { 0 };
    let mut winners: Vec<i64> = board.iter().filter(|e| e.points > nth).map(|e| e.player_id).collect();
    if nth > 0 {
        let mut pool: Vec<i64> = board.iter().filter(|e| e.points == nth).map(|e| e.player_id).collect();
        shuffle(&mut pool);
        let remaining = n - winners.len();
        winners.extend(pool.into_iter().take(remaining));
    }
    winners
}
