fn shuffle(ids: &mut [i64]) {
    if ids.len() < 2 { return; }
    let bytes = random_bytes(ids.len() * 8);
    for i in (1..ids.len()).rev() {
        let j = (u64::from_le_bytes(bytes[i*8..i*8+8].try_into().unwrap()) as usize) % (i + 1);
        ids.swap(i, j);
